.", "grade_level": "3º ao 5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF35LP30", "name": "Diferenciar discurso indireto e discurso direto, determinando o efeito de sentido de…", "description": "Diferenciar discurso indireto e discurso direto, determinando o efeito de sentido de verbos de enunciação e explicando o uso de variedades linguísticas no discurso direto, quando for o caso.", "grade_level": "3º ao 5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF35LP31", "name": "Identificar, em textos versificados, efeitos de sentido decorrentes do uso de recursos…", "description": "Identificar, em textos versificados, efeitos de sentido decorrentes do uso de recursos rítmicos e sonoros e de metáforas.", "grade_level": "3º ao 5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF67EF01", "name": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos, valorizando e…", "description": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais e etários.", "grade_level": "6º ao 7º Ano", "competency": "Educação Física", "subject": "Educação Física", "axis": "DA CONDUTA"}, {"code": "EF67EF02", "name": "Identificar as transformações nas características dos jogos eletrônicos em função dos…", "description": "Identificar as transformações nas características dos jogos eletrônicos em função dos avanços das tecnologias e nas respectivas exigências corporais colocadas por esses diferentes tipos de jogos.", "grade_level": "6º ao 7º Ano", "competency": "Educação Física", "subject": "Educação Física", "axis": "DA CONDUTA"}, {"code": "EF67EF03", "name": "Experimentar e fruir esportes de marca, precisão, invasão e técnico combinatórios,…", "description": "